import worksJson from './works.json';
import creditsJson from './credits.json';

// Artworks shown in Kunst: works.json (hand-written) + credits.json (generated by
// scripts/fetch-kunst-images.mjs: author and licence from Wikimedia Commons).
interface Work { wiki: string; title: string; artist: string; year: string; file?: string }
interface Credit { file: string; author: string; licence: string; licenceUrl?: string; page: string }

const WORKS = worksJson as Record<string, Work>;
const CREDITS = creditsJson as Record<string, Credit>;

export const hasWork = (key: string) => key in WORKS && key in CREDITS;

export interface WorkView {
  key: string;
  src: string;
  title: string;
  artist: string;
  year: string;
  credit: string; // "Foto: Autor, Lizenz"
  page: string;
}

export function workView(key: string): WorkView | null {
  const w = WORKS[key];
  const c = CREDITS[key];
  if (!w || !c) return null;
  const author = c.author === 'unbekannt' ? '' : `${c.author}, `;
  return {
    key,
    src: `/kunst/${key}.jpg`,
    title: w.title,
    artist: w.artist,
    year: w.year,
    credit: c.licence.toLowerCase().startsWith('public domain') ? `Gemeinfrei · Wikimedia Commons` : `Bild: ${author}${c.licence} · Wikimedia Commons`,
    page: c.page,
  };
}
